static __forceinline void build_loopout_mesh(Path *path, char *texture_a, char *texture_b)
{
    Vector3 *vertices = path->strip_mesh->vertices;
    cRFaceQuad *facequads = path->strip_mesh->facequads;

    int mesh_row;
    int mesh_column;
    int face_row;
    int face_column;
    int face_index;

    for (mesh_row = 0; mesh_row <= path->segment_count; ++mesh_row)
    {
        for (mesh_column = 0; mesh_column <= path->width_cells; ++mesh_column)
        {
            double lateral = (float)mesh_column - (float)path->width_cells * 0.5f;
            if (mesh_row != path->segment_count)
            {
                Vector3 lateral_offset = path->primary_samples[mesh_row].transform.basis_right * lateral;
                Vector3 generated_position = path->primary_samples[mesh_row].transform.position + lateral_offset;
                Vector3 *vertex = &vertices[mesh_column + mesh_row * (path->width_cells + 1)];
                *vertex = generated_position;
            }
            else
            {
                Vector3 lateral_offset = path->primary_samples[mesh_row - 1].transform.basis_right * lateral;
                Vector3 endpoint = path->primary_samples[mesh_row - 1].transform.position + Vector3(0.0f, 0.0f, 1.0f);
                Vector3 generated_position = endpoint + lateral_offset;
                Vector3 *vertex = &vertices[mesh_column + mesh_row * (path->width_cells + 1)];
                *vertex = generated_position;
            }
        }
    }

    for (face_row = 0; face_row < path->segment_count; ++face_row) {
        face_column = 0;
        if (path->width_cells > 0) {
            float v0 = (float)(face_row % 8) * 0.125f;
            float v1 = (float)(face_row % 8 + 1) * 0.125f;
            int next_column;
            do {
                face_index = 0;
                next_column = face_column + 1;
                float u0 = (float)face_column * 0.125f;
                float u1 = (float)(face_column + 1) * 0.125f;
                for (; face_index < 2; ++face_index) {
                    int face_array_index =
                        face_index
                        + 2 * (face_row * path->width_cells + face_column);
                    if (face_index == 0) {
                        facequads[face_array_index].header_word = 0;
                        facequads[face_array_index].vertex_0 = face_column + face_row * ((unsigned short)path->width_cells + 1);
                        facequads[face_array_index].vertex_1 = face_row * ((unsigned short)path->width_cells + 1) + face_column + 1;
                        facequads[face_array_index].vertex_2 =
                            (face_row + 1) * ((unsigned short)path->width_cells + 1) + face_column + 1;
                        facequads[face_array_index].vertex_3 =
                            face_column + (face_row + 1) * ((unsigned short)path->width_cells + 1);
                        if ((face_column & 1) == (face_row & 1))
                            facequads[face_array_index].texture_ref =
                                g_texture_refs.Add(texture_a, 0, 0);
                        else
                            facequads[face_array_index].texture_ref =
                                g_texture_refs.Add(texture_a, 0, 0);
                    } else {
                        facequads[face_array_index].header_word = 0;
                        facequads[face_array_index].vertex_0 = face_row * ((unsigned short)path->width_cells + 1) + face_column + 1;
                        facequads[face_array_index].vertex_1 = face_column + face_row * ((unsigned short)path->width_cells + 1);
                        facequads[face_array_index].vertex_2 =
                            face_column + (face_row + 1) * ((unsigned short)path->width_cells + 1);
                        facequads[face_array_index].vertex_3 =
                            (face_row + 1) * ((unsigned short)path->width_cells + 1) + face_column + 1;
                        if ((face_column & 1) == (face_row & 1))
                            facequads[face_array_index].texture_ref =
                                g_texture_refs.Add(texture_b, 0, 0);
                        else
                            facequads[face_array_index].texture_ref =
                                g_texture_refs.Add(texture_b, 0, 0);
                    }
                    if (face_index == 0) {
                        facequads[face_array_index].uv[0].u = u0;
                        facequads[face_array_index].uv[0].v = v0;
                        facequads[face_array_index].uv[1].u = u1;
                        facequads[face_array_index].uv[1].v = v0;
                        facequads[face_array_index].uv[2].u = u1;
                        facequads[face_array_index].uv[2].v = v1;
                        facequads[face_array_index].uv[3].u = u0;
                        facequads[face_array_index].uv[3].v = v1;
                    } else {
                        facequads[face_array_index].uv[0].u = u1;
                        facequads[face_array_index].uv[0].v = v0;
                        facequads[face_array_index].uv[1].u = u0;
                        facequads[face_array_index].uv[1].v = v0;
                        facequads[face_array_index].uv[2].u = u0;
                        facequads[face_array_index].uv[2].v = v1;
                        facequads[face_array_index].uv[3].u = u1;
                        facequads[face_array_index].uv[3].v = v1;
                    }
                }
                face_column = next_column;
            } while (next_column < path->width_cells);
        }
    }

}

